/* bbma-camarilla-ui.js — Camarilla pivots dashboard for the Analysis tab.
 * Reads window.PIVOTS_AUTO (generated by build-pivots.js, refreshed every 30 min
 * by the ifx poller): 18 symbols, each with R4..R1 / C / S1..S4 from the previous
 * closed daily bar (Range=H-L, step=Range*1.1, R1=C+step/12 ... R4=C+step/2).
 *
 * UX: grid of 18 symbol cards (select any one) -> full-ladder detail with
 * live-price marker + step-by-step calculation. Live prices come from
 * window.LiveFeed (gold/metal, crypto, FX); missing price = "—" (fail-closed,
 * the ladder still renders from the previous session).
 * Pure DOM, no external deps. Fails closed: no PIVOTS_AUTO -> one-line note.
 */
(function () {
  'use strict';
  var ORDER = ['XAUUSD', 'EURUSD', 'GBPUSD', 'USDJPY', 'AUDUSD', 'BTCUSD', 'ETHUSD', 'DXY',
    'USDMYR', 'NZDUSD', 'USDCAD', 'USDCHF', 'EURJPY', 'GBPJPY', 'EURGBP', 'AUDJPY', 'USDIDR', 'USDTHB'];
  var state = { sel: null };

  function esc(x) { return String(x == null ? '' : x).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function fmt(n, d) { if (!isFinite(n)) return '—'; return Number(n).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d }); }

  // Live price lookup: metal (XAU/XAG by short code), crypto (BTC/ETH), FX pair (BASE/QUOTE).
  function livePrice(id) {
    var LF = window.LiveFeed;
    if (!LF) return null;
    try {
      if (id === 'XAUUSD') return LF.metal ? LF.metal('XAU') : null;
      var p = LF.prices && LF.prices();
      if (id === 'BTCUSD') return p && p.crypto ? p.crypto.BTC : null;
      if (id === 'ETHUSD') return p && p.crypto ? p.crypto.ETH : null;
      if (id === 'DXY') return null; // index — no keyless live source wired
      var base = id.slice(0, 3), quote = id.slice(3);
      return LF.priceFor ? LF.priceFor(base + '/' + quote) : null;
    } catch (e) { return null; }
  }

  function symbols() {
    var pv = window.PIVOTS_AUTO;
    if (!pv || !pv.symbols) return [];
    var out = ORDER.filter(function (id) { return pv.symbols[id] && pv.symbols[id].ok; });
    // include any symbol present but not in the preferred order (universe can grow)
    Object.keys(pv.symbols).forEach(function (id) {
      if (pv.symbols[id] && pv.symbols[id].ok && out.indexOf(id) === -1) out.push(id);
    });
    return out;
  }

  function posTag(pos) {
    var p = Math.round((pos || 0) * 100);
    if (p >= 60) return { cls: 'up', txt: 'bull close ' + p + '%' };
    if (p <= 40) return { cls: 'dn', txt: 'bear close ' + p + '%' };
    return { cls: 'mid', txt: 'mid close ' + p + '%' };
  }

  function renderGrid() {
    var box = document.getElementById('cp-symbol-chips');
    var det = document.getElementById('cp-detail');
    var stamp = document.getElementById('cp-stamp');
    if (!box || !det) return;
    var ids = symbols();
    if (!ids.length) {
      box.innerHTML = '';
      det.innerHTML = '<div class="note">No pivot data loaded yet — the poller regenerates <code>pivots.js</code> every 30 min. Reload in a moment.</div>';
      if (stamp) stamp.textContent = '—';
      return;
    }
    if (!state.sel || ids.indexOf(state.sel) === -1) state.sel = 'XAUUSD';
    box.innerHTML = '<div class="cp-grid">' + ids.map(function (id) {
      var s = window.PIVOTS_AUTO.symbols[id];
      var d = s.decimals != null ? s.decimals : 2;
      var px = livePrice(id);
      var pos = posTag(s.closePos);
      var p2 = Math.round((s.closePos || 0) * 100);
      return '<div class="cp-card' + (id === state.sel ? ' on' : '') + '" data-cp-id="' + esc(id) + '">' +
        '<div class="cp-sym">' + esc(s.label || id) + '</div>' +
        '<div class="cp-pos">' + esc(pos.txt) + ' · ' + esc(s.session || '') + '</div>' +
        '<div class="cp-px">' + (px != null ? fmt(px, d) : '—') + '</div>' +
        '<div class="cp-bar"><i style="width:' + p2 + '%"></i></div>' +
        '</div>';
    }).join('') + '</div>';
    box.querySelectorAll('.cp-card').forEach(function (c) {
      c.addEventListener('click', function () { state.sel = c.dataset.cpId; renderGrid(); });
    });
    renderDetail();
    var pv = window.PIVOTS_AUTO;
    if (stamp) stamp.textContent = 'session ' + (pv.session || '—') + ' · generated ' + (pv.generatedAt || '—') + ' · ' + ids.length + ' symbols ok';
  }

  function renderDetail() {
    var det = document.getElementById('cp-detail');
    if (!det) return;
    var pv = window.PIVOTS_AUTO;
    var s = pv && pv.symbols && pv.symbols[state.sel];
    if (!s) { det.innerHTML = ''; return; }
    var d = s.decimals != null ? s.decimals : 2;
    var px = livePrice(state.sel);
    var lo = s.S4, hi = s.R4;
    var span = (hi - lo) || 1;
    var posOf = function (v) { return Math.max(0, Math.min(100, (v - lo) / span * 100)); };
    var rows = [
      { k: 'R4', v: s.R4, cls: 'res', note: 'trend-day breakout' },
      { k: 'R3', v: s.R3, cls: 'res', note: 'mean-reversion target' },
      { k: 'R2', v: s.R2, cls: 'res' },
      { k: 'R1', v: s.R1, cls: 'res' },
      { k: 'C', v: s.c, cls: 'pp', note: 'previous close (pivot axis)' },
      { k: 'S1', v: s.S1, cls: 'sup' },
      { k: 'S2', v: s.S2, cls: 'sup' },
      { k: 'S3', v: s.S3, cls: 'sup', note: 'mean-reversion target' },
      { k: 'S4', v: s.S4, cls: 'sup', note: 'trend-day breakout' }
    ];
    var priceHtml = (px != null)
      ? '<div class="cp-price" style="left:' + posOf(px) + '%"><i>' + fmt(px, d) + '</i></div>'
      : '';
    det.innerHTML =
      '<div class="cp-hero">' +
      '  <div class="cp-h-title">' + esc(s.label || state.sel) + ' · Camarilla · prev session ' + esc(s.session || '—') + '</div>' +
      '  <div class="cp-h-meta">H ' + fmt(s.h, d) + ' · L ' + fmt(s.l, d) + ' · C ' + fmt(s.c, d) + ' · Range ' + fmt(s.range, d) + ' · live ' + (px != null ? fmt(px, d) : '—') + '</div>' +
      '</div>' +
      '<div class="cp-ladder">' + rows.map(function (r) {
        var isLive = px != null && px >= r.v - span * 0.02 && px <= r.v + span * 0.02;
        var delta = (px != null) ? ((px - r.v) / (Math.pow(10, -d) || 1)) : null;
        return '<div class="cp-row' + (isLive ? ' is-live' : '') + '">' +
          '<span class="cp-lab ' + r.cls + '">' + r.k + '</span>' +
          '<span class="cp-val">' + fmt(r.v, d) + '</span>' +
          (delta != null ? '<span class="cp-delta">' + (delta >= 0 ? '+' : '') + delta.toFixed(0) + ' pips</span>' : '') +
          '<span class="cp-track"><span class="cp-seg" style="left:0;right:0"></span>' + priceHtml + '</span>' +
          (r.note ? '<span class="cp-delta" title="' + esc(r.note) + '"></span>' : '') +
          '</div>';
      }).join('') + '</div>' +
      '<div class="cp-calc">Calc: <b>Range</b> = H−L = ' + fmt(s.h, d) + ' − ' + fmt(s.l, d) + ' = <b>' + fmt(s.range, d) + '</b> · <b>step</b> = Range×1.1 = <b>' + fmt(s.range * 1.1, d) + '</b><br>' +
      'R1 = C + step/12 = ' + fmt(s.c, d) + ' + ' + fmt(s.range * 1.1 / 12, d) + ' = <b>' + fmt(s.R1, d) + '</b> · R2 = C + step/6 = <b>' + fmt(s.R2, d) + '</b> · R3 = C + step/4 = <b>' + fmt(s.R3, d) + '</b> · R4 = C + step/2 = <b>' + fmt(s.R4, d) + '</b><br>' +
      'S1 = C − step/12 = <b>' + fmt(s.S1, d) + '</b> · S2 = C − step/6 = <b>' + fmt(s.S2, d) + '</b> · S3 = C − step/4 = <b>' + fmt(s.S3, d) + '</b> · S4 = C − step/2 = <b>' + fmt(s.S4, d) + '</b><br>' +
      'Close position = (C−L)/Range = <b>' + Math.round((s.closePos || 0) * 100) + '%</b> (0%=session low, 100%=session high). ' +
      'R3/S3 mean-reversion targets · R4/S4 trend-day breakout. Research context only.</div>';
  }

  // Live-price refresh (2s): update ONLY the price cells + detail marker, so the
  // grid rebuild (which resets scroll/click state) only happens when the data or
  // selection changes.
  function tick() {
    var box = document.getElementById('cp-symbol-chips');
    if (!box || !window.PIVOTS_AUTO) return;
    box.querySelectorAll('.cp-card').forEach(function (c) {
      var id = c.dataset.cpId;
      var s = window.PIVOTS_AUTO.symbols[id];
      if (!s) return;
      var d = s.decimals != null ? s.decimals : 2;
      var cell = c.querySelector('.cp-px');
      if (cell) { var px = livePrice(id); cell.textContent = px != null ? fmt(px, d) : '—'; }
    });
    renderDetail(); // re-place the live marker inside the ladder
  }

  function boot() {
    renderGrid();
    setInterval(tick, 2000);
  }
  window.BBMA_Camarilla = { render: renderGrid };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
